const fs = require('fs');
const path = require('path');

// Function to generate a random string of 5 alphanumeric characters
const generateRandomString = () => {
  return Math.random().toString(36).substring(2, 7);
};

class CacheBusterPlugin {
  constructor(options) {
    this.htmlFilePaths = options.htmlFilePaths || []; // Array of HTML file paths in the source directory
    this.filesToCacheBust = options.filesToCacheBust || []; // Array of filenames to cache bust
  }

  apply(compiler) {
    // Register a function to run before the build process starts
    compiler.hooks.beforeCompile.tap('CacheBusterPlugin', () => {
      const randomString = generateRandomString();

      this.htmlFilePaths.forEach((htmlFilePath) => {
        // Resolve the absolute path of the HTML file from the project root
        const absoluteHtmlFilePath = path.resolve(htmlFilePath);

        // Check if the file exists before attempting to read
        if (!fs.existsSync(absoluteHtmlFilePath)) {
          console.warn(`Source HTML file not found: ${absoluteHtmlFilePath}`);
          return;
        }

        // Read the HTML file from the source directory
        fs.readFile(absoluteHtmlFilePath, 'utf8', (err, htmlContent) => {
          if (err) {
            console.error(`Error reading source HTML file at ${absoluteHtmlFilePath}:`, err.message);
            return;
          }

          let updatedHtmlContent = htmlContent;

          // Update only relevant tags
          this.filesToCacheBust.forEach((fileName) => {
            // Match src/href attributes containing the specified filename without query string
            const regex = new RegExp(`(src|href)="([^"]*${fileName})(\\?v=[^"]*)?"`, 'g');
            updatedHtmlContent = updatedHtmlContent.replace(regex, `$1="$2?v=${randomString}"`);
          });

          // Write the updated HTML back to the file
          fs.writeFile(absoluteHtmlFilePath, updatedHtmlContent, 'utf8', (err) => {
            if (err) {
              console.error(`Error writing updated source HTML file at ${absoluteHtmlFilePath}:`, err.message);
              return;
            }

            console.log(`Source HTML file ${htmlFilePath} updated with new cache-busting string:`, randomString);
          });
        });
      });
    });
  }
}

module.exports = CacheBusterPlugin;
